style.css:
@-moz-document domain("jira.atlassian.com"), url-prefix("https://jira") {
.aui-header {
	background-color: #333333;
}
.aui-nav-link.aui-dropdown2-trigger {
	color: white;
}
.aui-page-panel {
	background-color: #333333;
}
.aui-sidebar-body {
	background-color: #333333;
}
.aui-sidebar-group-tier-one .aui-nav-item {
	
}
.aui-sidebar-footer {
    background-color: #333333;
}
.ghx-column-headers  .ghx-column {
	background-color: #333333;
}
#ghx-column-headers {
	background-color: #333333;
}
#ghx-pool {
	background-color: #333333;
}
.ghx-column h2 {
 	color: white;   
}
#issue-content {
    background-color: #333333;
}
#stalker {
 	background-color: #333333;   
}
#summary-val {
 	color: white;   
}

.ghx-summary {
	color: white;
}
.js-detailview.ghx-issue.ghx-flagged {
 	background-color: #610000;   
}
.js-issue.ghx-flagged {
    background-color: #610000;
}
.js-issue.ghx-flagged .ghx-end {
    background-color: #610000;
}
.aui-group {
	background-color: #333333;
    color: white;
}

.ghx-issue-compact .ghx-end {
	background: #333333;
}

.ghx-end.ghx-row {
	background-color: #424949;
}
.js-issue.ghx-selected.ghx-end.ghx-row {
	background-color: #424949;
}
.subnavigator-title {
	color:  #4475B3;
}
.ghx-sprint-group {
	background-color: #333333;
}
.ghx-backlog-container {
	background-color: #333333;
}
.ghx-issue {
	background-color: #424949;
}
.js-issue {
	background-color: #424949;
}
.js-issue.ghx-selected {
	background-color: #424949;
}
.ghx-swimlane-header:after {
    background: transparent;
    box-shadow: none;
}
.ghx-columns .ghx-column {
    background: rgba(0, 0, 0, .2);
    padding: 3px;
}
.ghx-column-headers,
.ghx-columns {
    border-spacing: 6px 0;
}
.ghx-swimlane-header {
    color: white;
}
.ghx-name {
	color: white;
}
.ghx-issue.ghx-selected{
	background-color: #424949;
}
.ghx-issue {
    border-radius: 3px;
    min-height: 100px;
    margin: 10px 4px;
    border: 1px solid rgba(0, 0, 0, .05);
    box-shadow: 2px 2px 2px 1px rgba(0, 0, 0, .2);
}
.ghx-parent-group {
    border-left: 3px solid rgba(255, 255, 255, .5);
    padding-bottom: 3px;
}
.ghx-parent-stub,
.ghx-parent-stub .ghx-group,
.ghx-parent-stub .ghx-key,
.ghx-parent-stub .ghx-summary {
    background: transparent;
    border: none;
}
.ghx-parent-stub {
    border-bottom: 2px solid #ddd;
}
.ghx-issue-subtask {
    margin-left: 3px;
}
.ghx-issue .ghx-issue-content {
    min-height: 48px;
    padding-left: 10px;
    padding-bottom: 32px;
}
.ghx-issue .ghx-highlighted-fields {
    padding-right: 0px;
    margin: 8px 0px;
}
.ghx-issue .ghx-highlighted-fields .ghx-highlighted-field {
    max-width: 100%;
    width: 100%;
}
.ghx-issue .ghx-highlighted-fields .ghx-highlighted-field span {
    display: block;
}
.ghx-issue .ghx-extra-fields .ghx-extra-field-row {
    display: inline-block;
}
.ghx-issue .ghx-extra-fields .ghx-extra-field {
    display: inline-block;
    background-color: #eee;
    border-radius: 4px;
    color: #333;
    padding: 4px 8px;
    margin-right: 4px;
    font-size: 12px;
}
.ghx-issue .ghx-avatar {
    left: 12px;
    bottom: 4px;
    top: auto;
    right: auto;
}
.ghx-issue .ghx-avatar img {
    border-radius: 50%;
    width: 24px;
    height: 24px;
}
.ghx-issue .ghx-days {
    display: none;
}
.ghx-issue .ghx-type {
    left: 42px;
    bottom: 4px;
    right: auto;
    top: auto;
    width: 24px;
    height: 24px;
}
.ghx-issue .ghx-type img,
.ghx-issue .ghx-flags img {
    width: 24px;
    height: 24px;
}
.ghx-issue .ghx-key a {
    font-weight: 700;
}
.ghx-issue .ghx-grabber {
    height: 5px;
    left: 0;
    position: absolute;
    text-indent: -9999em;
    top: 0;
    width: 100%;
    border-top-left-radius: 4px;
    border-top-right-radius: 4px;
}
.ghx-issue .ghx-end,
.ghx-issue.ghx-selected .ghx-end,
.ghx-issue:hover .ghx-end,
.ghx-issue.ghx-selected:hover .ghx-end {
    bottom: 7px;
    left: 94px;
    position: absolute;
    right: auto;
    top: auto;
    background: none;
    box-shadow: none;
}
.ghx-issue .ghx-end .aui-badge {
    font-size: 14px
}
.ghx-issue .ghx-flags {
    left: 68px;
    top: auto;
    right: auto;
    bottom: 4px;
    width: 24px;
    height: 24px;
}
.ghx-issue .ghx-flags .ghx-priority[title=P1],
.ghx-issue .ghx-flags .ghx-priority[title=P2] {
    color: #CE0000;
}
.ghx-issue .ghx-flags .ghx-priority[title=P3] {
    color: #EA7D24;
}
.ghx-issue .ghx-flags .ghx-priority[title=P4],
.ghx-issue .ghx-flags .ghx-priority[title=P5] {
    color: #2A8735;
}
/* Responsive */

.ghx-band-2 .ghx-issue .ghx-issue-content {
    padding-left: 5px;
    min-height: 55px;
}
.ghx-band-2 .ghx-issue .ghx-type {
    top: auto;
    right: 7px;
    bottom: 21px;
}
.aui-badge {
	color: white;
}
.ghx-band-2 .ghx-issue .ghx-flags {
    top: auto;
    right: 7px;
    bottom: 5px;
}
.ghx-stats {
	background-color: #333333;
}
.ghx-end {
	background-color: #333333;
}
.ghx-marker {
	background-color: #333333;
}
/* Below WIP Limit */
.ghx-column-headers .ghx-column.ghx-busted-min {
 	background-color: #333333;   
}
.ghx-columns .ghx-column.ghx-busted.ghx-busted-min {
	background-color: #707B7C;
}

/* WIP Limit Reached or Exceeded */
.ghx-column-headers .ghx-column.ghx-busted-max {
 	background-color: #333333;   
}
.ghx-columns .ghx-column.ghx-busted.ghx-busted-max {
    background-color: #1A5276;
}
/* Planning, In Progress, and QA days tracking */
.ghx-column:nth-child(2) .ghx-issue.ghx-days-3,
.ghx-column:nth-child(3) .ghx-issue.ghx-days-3,
.ghx-column:nth-child(4) .ghx-issue.ghx-days-3 {
